    description: "Ellenőrzi a szerver elérhetőségét",
    enabled: true,
    category: "server",
    parameters: [],
  },
  {
    id: "agent_list",
    name: "agent_list",
    description: "Aktív ágensek listázása",
    enabled: true,
    category: "server",
    parameters: [],
  },
  {
    id: "agent_registry",
    name: "agent_registry",
    description: "Összes ágens definíció listázása",
    enabled: true,
    category: "server",
    parameters: [],
  },
  {
    id: "agent_delegate",
