// Minden Node.js-specifikus függőséget dinamikusan kell importálni.

async function main() {
  // Feltételes végrehajtás Node.js környezetben
  if (
    typeof process !== "undefined" &&
    process.versions &&
    process.versions.node
  ) {
    // Dinamikus importok a Node-natív modulok Worker buildjeiben való csomagolásának megakadályozására
    await import("dotenv/config");

