               <span className="text-[10px] font-mono font-bold text-zinc-400">{isConnected ? healthStatus?.status === 'HEALTHY' ? "CORE_ONLINE" : "CORE_DEGRADED" : "CORE_OFFLINE"}</span>
            </div>
            <ThemeToggle />
          </div>
        </header>

        <div
          className="flex-1 grid px-6 pb-4 pt-2 relative z-0 min-h-0"
          style={{
            gridTemplateAreas: currentLayout.gridTemplateAreas.map(area => `'${area}'`).join(' '),
            gridTemplateColumns: currentLayout.gridTemplateColumns || '1fr',
            gridTemplateRows: currentLayout.gridTemplateRows || 'auto 1fr auto',
            gap: '1.5rem' // Equivalent to gap-6
          }}
        >
          <DynamicSidebar activeTab={activeTab} onTabChange={setActiveTab} style={{ gridArea: 'sidebar' }} />

          <main className="glass-panel rounded-2xl border-white/5 relative z-10 flex flex-col overflow-hidden bg-black/20" style={{ gridArea: 'main-top' }}>
            <div 
              key={currentLayout.id} // Key off currentLayout.id to re-render when layout changes
              className="flex-1 min-h-0 overflow-y-auto custom-scrollbar scroll-smooth p-4" // General padding
            >
              <div className="h-full w-full grid"
                style={{
                  gridTemplateAreas: currentLayout.gridTemplateAreas.map(area => `'${area}'`).join(' '),
                  gridTemplateColumns: currentLayout.gridTemplateColumns,
                  gridTemplateRows: currentLayout.gridTemplateRows,
                  gap: '1rem', // Tailwind gap-4 equivalent
                }}
              >
                {Object.entries(currentLayout.widgetAssignments).map(([widgetId, gridArea]) => {
                  const widget = WIDGET_REGISTRY[widgetId];
                  if (!widget) return null; // Don't render if widget not found

                  const Component = widget.component;

                  return (
                    <div key={widgetId} style={{ gridArea }} className="relative overflow-hidden rounded-2xl border border-white/5 bg-black/20 backdrop-blur-md">
                      <div className="h-full w-full overflow-hidden">
                        <Component />
                      </div>
                    </div>
                  );
                  // ... rest of the map function
                })}
              </div>
            </div>
          </main>
        </div>
      </div>
      </LayoutProvider>
    </>
  );
}

