        process_control: 'ops-alerts', // Process intervention/alerts
      },
    },
    {
      id: 'focused-mode',
      name: 'Focused Mode',
      description: 'Highlights a single widget for detailed view.',
      gridTemplateAreas: [
        '"header header header"',
        '"sidebar focused-main focused-main"',
        '"sidebar focused-main focused-main"',
        '"sidebar footer footer"'
      ],
      gridTemplateColumns: 'auto 1fr 1fr',
      gridTemplateRows: 'auto 2fr 1fr auto',
      widgetAssignments: {
        'selected-widget': 'focused-main',
      },
    },
  ],
};

interface LayoutContextType {
  currentLayout: LayoutMode;
  setLayoutMode: (modeId: LayoutModeId) => void;
  layouts: DashboardLayoutConfig;
}

const LayoutContext = createContext<LayoutContextType | undefined>(undefined);

export function LayoutProvider({ children }: { children: ReactNode }) {
  const [activeLayoutId, setActiveLayoutId] = useState<LayoutModeId>(defaultLayoutConfig.defaultMode);

  const currentLayout = defaultLayoutConfig.modes.find(mode => mode.id === activeLayoutId) || defaultLayoutConfig.modes[0];

  const setLayoutMode = (modeId: LayoutModeId) => {
    if (defaultLayoutConfig.modes.some(mode => mode.id === modeId)) {
      setActiveLayoutId(modeId);
    } else {
      console.warn(`Attempted to set unknown layout mode: ${modeId}`);
    }
  };

  return (
    <LayoutContext.Provider value={{ currentLayout, setLayoutMode, layouts: defaultLayoutConfig }}>
      {children}
    </LayoutContext.Provider>
  );
}

export function useLayout() {
  const context = useContext(LayoutContext);
  if (context === undefined) {
    throw new Error('useLayout must be used within a LayoutProvider');
  }
  return context;
}

