    label: "Track Progress",
    component: TrackProgressWidget,
    defaultSize: { w: 4, h: 5 }
  },
  test_results: {
    id: "test_results",
    label: "Precision Tests",
    component: TestResultsWidget,
    defaultSize: { w: 4, h: 5 }
  },
  suggested_tasks: {
    id: "suggested_tasks",
    label: "Suggested Tasks",
    component: SuggestedTasksWidget,
    defaultSize: { w: 4, h: 6 }
  },
  task_queue: {
    id: "task_queue",
    label: "Task Queue",
    component: TaskQueueMonitor,
    defaultSize: { w: 6, h: 8 }
  },
  agent_chatter: {
    id: "agent_chatter",
    label: "Agent Chatter",
    component: LiveChatterWidget,
    defaultSize: { w: 6, h: 8 }
  },
  scheduled_tasks: {
