            const widget = WIDGET_REGISTRY[widgetId];
            if (!widget) return null;

            const Component = widget.component;

            return (
              <div key={widgetId} style={{ gridArea }} className="relative overflow-hidden rounded-2xl border border-white/5 bg-black/20 backdrop-blur-md">
                <div className="h-full w-full overflow-hidden">
                  <Component />
                </div>
              </div>
            );
          })}

          {/* Fallback for footer area if needed */}
          <footer style={{ gridArea: 'footer' }} className="flex items-center justify-between px-4 py-2 border-t border-white/5 bg-black/40 backdrop-blur-md rounded-xl hidden lg:flex">
            <span className="text-[10px] font-mono text-zinc-500">SYSTEM_READY // GRID_ACTIVE</span>
            <span className="text-[10px] font-mono text-primary/40">MODE: {currentLayout.id.toUpperCase()}</span>
          </footer>
        </div>
      </div>
    </>
  );
}

