import { useState } from "react";
import { cn } from "@/lib/utils";
import { useLayout } from "@/lib/layout/LayoutContext";

export function MissionControlLayout() {
  const [activeTab, setActiveTab] = useState<string>("dashboard");
  const { currentLayout, setLayoutMode } = useLayout();

  return (
    <div className="min-h-screen bg-black text-white p-20 flex flex-col gap-6">
      <h1 className="text-5xl font-bold text-primary">Mission Control Isolated</h1>
      <p className="text-zinc-400">Ez egy izolált nézet a végtelen hurok hibakereséséhez.</p>

      <div className="flex gap-4">
        <button 
          onClick={() => setLayoutMode('default-dashboard')}
          className="px-6 py-3 bg-zinc-800 hover:bg-zinc-700 rounded-xl transition-colors"
        >
          Default Layout
        </button>
        <button 
          onClick={() => setLayoutMode('dev-mode')}
          className="px-6 py-3 bg-zinc-800 hover:bg-zinc-700 rounded-xl transition-colors"
        >
          Developer Mode
        </button>
        <button 
          onClick={() => setLayoutMode('ops-mode')}
          className="px-6 py-3 bg-zinc-800 hover:bg-zinc-700 rounded-xl transition-colors"
        >
          Operations Mode
        </button>
      </div>

      <div className="mt-10 p-6 bg-zinc-900 rounded-2xl border border-white/5 font-mono text-xs overflow-auto max-h-[400px]">
        <h2 className="text-primary mb-4">// Current Layout State</h2>
        <pre>{JSON.stringify(currentLayout, null, 2)}</pre>
      </div>
    </div>
  );
}

